INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('43edf712-d630-4462-b3d2-8cb62fa8aa8e', 'b2b2b2b2-3030-4000-8000-000000000002', 13, 'Dia 13 — Perdoar-se', 'Semana 2: Processar', '{"pch": "Se confessarmos os nossos pecados, Ele \u00e9 fiel e justo para nos perdoar\u2026 Voc\u00ea tamb\u00e9m pode se perdoar.", "verse": "1Jo 1,9", "lectio": "Leia 1Jo 1,5-10. Andar na luz.", "practice": "Olhe no espelho e diga: Eu te perdoo. Eu te amo.", "question": "O que voc\u00ea fez que ainda n\u00e3o se perdoou?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;